insert into public.recipes (id, status, cover_image, prep_minutes, cook_minutes, servings, video_url, family_id, variant_label, variant_image, related_post_ids) values ('recipe-mazurek', 'published', 'https://kdrbtwwhmzszzukcffsu.supabase.co/storage/v1/object/public/recipe-media/recipes/recipe-mazurek/bfb03b99-ac14-47da-b69d-c24dc641771f.webp', 35, 40, 12, null, null, '{}'::jsonb, '', array['post-wielkanoc', 'post-makowiec-technik', 'post-polenladen']::text[]) on conflict (id) do update set status = excluded.status, cover_image = excluded.cover_image, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, servings = excluded.servings, video_url = excluded.video_url, family_id = excluded.family_id, variant_label = excluded.variant_label, variant_image = excluded.variant_image, related_post_ids = excluded.related_post_ids, updated_at = now();
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-mazurek', 'de', 'Mazurek orzechowy', 'mazurek', 'Flacher Osterkuchen auf Mürbeteig mit Nuss-Honig-Belag, eine festliche Hausvariante, die sich klar von Babka, Sernik oder Makowiec unterscheidet.', '[{"text":"Für den Boden Mehl, kalte Butter, Zucker, Ei und eine Prise Salz zu einem glatten Mürbeteig verkneten. Zu einer Scheibe formen, in Folie wickeln und 30 Minuten kühlen.","tip":"Das ist ein kurzer, flacher Teig, kein Hefegugelhupf wie [Babka](/de/rezepte/babka). Den Rahmen für den ganzen Ostertisch liefert der [Wielkanoc-Speiseplan](/de/blog/wielkanoc-speiseplan)."},{"text":"Ein Backblech oder eine flache Form von etwa 30 mal 40 Zentimetern fetten, den Teig dünn auf etwa 5 Millimeter ausrollen, einlegen und die Ränder hochdrücken. Mit einer Gabel mehrfach einstechen.","tip":"Eine gerollte Mohnrolle bleibt [Makowiec](/de/rezepte/makowiec) vorbehalten, die Käsekuchen-Linie führt zu [Sernik](/de/rezepte/sernik)."},{"text":"Den Boden bei 180 Grad, bei Umluft etwas niedriger, 12 bis 15 Minuten vorbacken, bis er matt und leicht golden aussieht, dann herausnehmen.","tip":"Ein zu lange vorgebackener Boden wird beim zweiten Backgang leicht zu dunkel, deshalb reicht hier ein leichtes Anbräunen völlig aus."},{"text":"Für den Belag gehackte Nüsse, je nach Hausbrauch Walnuss, Haselnuss oder Mandel, mit Butter, Honig oder Zucker und einer Prise Salz kurz in der Pfanne rösten, bis die Masse bindet. Gleichmäßig auf dem heißen Boden verteilen.","tip":"Nüsse und guten Honig findest du oft im [Polenladen](/de/blog/polenladen-einkaufen). Wie Hefeteig sich anfühlt, zeigt zwar die [Makowiec-Technik](/de/blog/makowiec-technik), die gerollte Mohnvariante bleibt aber allein dem Makowiec vorbehalten."},{"text":"Weitere 15 bis 20 Minuten backen, bis der Belag goldbraun und fest geworden ist. Abkühlen lassen, dann in Rauten schneiden. Optional mit etwas Puderzucker oder getrockneten Früchten garnieren.","tip":"Den festlichen Rahmen für den ganzen Ostertisch liefert der [Wielkanoc-Speiseplan](/de/blog/wielkanoc-speiseplan), der Fokus hier bleibt trotzdem klar bei diesem einen Mazurek."}]'::jsonb, 'Mazurek orzechowy, flach und knusprig-nussig, festlich und schnittfest, Ostern ohne hohen Turmkuchen. Der Name Mazurek geht auf „Mazur“ zurück, das alte Wort für einen Bewohner Masowiens, ein Mazurek war also ursprünglich schlicht ein „masowischer Kuchen“, genau wie der gleichnamige Tanz ein masowischer Tanz ist. Die ältesten polnischen Wörterbücher kannten dabei noch keine Verbindung zu Ostern: Bei Linde war ein Mazurek Anfang des 19. Jahrhunderts einfach ein „Kuchen aus Mandeln“. Seine Wurzeln reichen zurück zu orientalischer Mandelkonfekt-Kunst, die über osmanische Handelskontakte im 17. Jahrhundert nach Polen kam und in den Küchen der Adelshöfe verfeinert wurde, in Klosterküchen soll Ähnliches schon im Mittelalter gebacken worden sein. Fest mit Ostern verbunden wurde der Mazurek erst in Wörterbüchern nach dem Zweiten Weltkrieg. Genau diese Herkunft erklärt die charakteristische Form: ein dünner, knuspriger Boden mit einem reichen Belag obenauf, statt eines hohen, aufgehenden Kuchens. Das ist weder der hohe Hefegugelhupf [Babka](/de/rezepte/babka) noch der Quarkkuchen [Sernik](/de/rezepte/sernik) noch die Mohnrolle [Makowiec](/de/rezepte/makowiec) noch der Gewürzkuchen [Piernik](/de/rezepte/piernik).

## Einkaufen und kochen

Mehl, kalte Butter, Zucker und Ei bilden den Boden, gemischte Nüsse und Honig den Belag, beides findest du oft besonders frisch im [Polenladen](/de/blog/polenladen-einkaufen). Fehlt eine bestimmte Nusssorte, hilft ein ehrlicher Ersatz laut den [Ersatzprodukten DE](/de/blog/ersatzprodukte-de) weiter. Hefe braucht dieses Rezept nicht, wer das Gefühl für Hefeteig sucht, wird eher bei der [Makowiec-Technik](/de/blog/makowiec-technik) fündig. Als Form reicht ein flaches Blech, eine Gugelhupfform wie bei der Babka ist hier nicht nötig.

Der Mürbeteig sollte kurz und kalt verarbeitet werden, warmes Kneten macht ihn zäh statt kurz und mürbe. Nach dem dünnen Ausrollen wird der Boden vorgebacken, danach kommen die mit Butter und Honig gerösteten Nüsse sofort heiß darauf. Der zweite Backgang setzt den Belag fest, ohne den Boden zu verbrennen, deshalb sollte er beim ersten Mal nur leicht golden werden. Eine zu dicke Teigschicht wirkt schnell wie ein Keksboden ohne den typischen Mazurek-Charakter, während zu wenig Belag den Kuchen karg erscheinen lässt. Geschnitten wird erst nach vollständigem Abkühlen, heiß bricht der Belag sonst leicht.

In Deutschland wird oft am Samstag gebacken und am Sonntag nur noch angerichtet, das entlastet den Ostermorgen spürbar. Kinder dürfen Nüsse abzählen und die Rauten einteilen, der heiße Ofen bleibt bei den Erwachsenen. Ein Blech reicht für viele Gäste, Qualität schlägt hier drei verschiedene Kuchen. Der Einkauf lohnt sich früh im [Polenladen](/de/blog/polenladen-einkaufen), bevor die Nuss- und Honigregale vor Ostern leer sind.

## Am Tisch

In Rauten oder Rechtecken auf einer Platte, optional mit getrockneten Früchten dekoriert, am Ostertisch neben Żurek und bunten Eiern. Wer Höhe und Hefeteig sucht, findet das bei [Babka](/de/rezepte/babka), wer Quark bevorzugt, bei [Sernik](/de/rezepte/sernik), und wer die Mohnspirale möchte, bei [Makowiec](/de/rezepte/makowiec). Luftdicht verpackt bleibt der Belag mehrere Tage knusprig-nussig.

Ein zu dicker Boden erdrückt schnell den feinen Belag, und wer den Belag ohne Vorbacken des Bodens aufträgt, riskiert einen matschigen Kuchen. Mit dem hohen [Babka](/de/rezepte/babka) oder dem Quarkkuchen [Sernik](/de/rezepte/sernik) verwechselt man ihn schnell, dabei ist die flache Form gerade sein Markenzeichen. Wer den Kuchen noch heiß schneidet, bekommt einen brechenden Belag statt sauberer Rauten.

Ein Kajmak-Belag statt Nüssen ist eine verbreitete Hausvariante, die sich ehrlich im Titel ankündigen lässt, ebenso eine Version nur mit Walnüssen oder mit getrockneten Aprikosen. Passende Nachbarn sind [Babka](/de/rezepte/babka), [Sernik](/de/rezepte/sernik), [Makowiec](/de/rezepte/makowiec) und [Piernik](/de/rezepte/piernik). Zum Anlass passt der [Wielkanoc-Speiseplan](/de/blog/wielkanoc-speiseplan), und Einkaufshilfen liefern der [Polenladen](/de/blog/polenladen-einkaufen) und die [Ersatzprodukte](/de/blog/ersatzprodukte-de).', 'Mazurek Rezept | Osterkuchen polnisch orzechowy | Alemniam', 'Mazurek orzechowy: flacher Mürbeteig mit Nussbelag. Bilingual, Wielkanoc-tauglich, klar getrennt von Babka, Sernik und Makowiec.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-mazurek', 'pl', 'Mazurek orzechowy', 'mazurek', 'Płaski mazurek na kruchym spodzie z orzechowo-miodowym wierzchem, świąteczna wersja domowa, wyraźnie inna niż babka, sernik czy makowiec.', '[{"text":"Na spód zagnieć mąkę, zimne masło, cukier, jajko i szczyptę soli na gładkie kruche ciasto. Uformuj placek, owiń folią i chłodź 30 minut.","tip":"To krótki, płaski spód, a nie drożdżowa [babka](/pl/rezepte/babka). Ramę na cały stół wielkanocny daje [menu wielkanocne](/pl/blog/menu-wielkanocne)."},{"text":"Natłuść blachę lub płaską formę o wymiarach około 30 na 40 centymetrów, rozwałkuj ciasto cienko na około 5 milimetrów, ułóż je i podnieś brzegi. Nakłuj widelcem w kilku miejscach.","tip":"Zwijana rolada makowa zostaje przy [makowcu](/pl/rezepte/makowiec), linia sernikowa prowadzi do [sernika](/pl/rezepte/sernik)."},{"text":"Podpiecz spód w 180 stopniach, przy termoobiegu nieco niżej, przez 12 do 15 minut, aż będzie matowy i lekko złoty, potem wyjmij.","tip":"Zbyt długo podpieczony spód łatwo się przypali podczas drugiego pieczenia, dlatego wystarczy tu lekkie zarumienienie."},{"text":"Na wierzch posiekane orzechy, według domu włoskie, laskowe lub migdały, z masłem, miodem lub cukrem i szczyptą soli krótko podgrzej na patelni, aż masa zwiąże się. Rozprowadź równomiernie na gorącym spodzie.","tip":"Orzechy i dobry miód znajdziesz często w [sklepie polskim](/pl/blog/sklep-polski-zakupy). Wyczucie ciasta drożdżowego pokazuje [technika makowca](/pl/blog/makowiec-technika), ale zwijana wersja makowa zostaje wyłącznie przy makowcu."},{"text":"Piecz kolejne 15 do 20 minut, aż wierzch będzie złoty i związany. Ostudź, pokrój w romby. Opcjonalnie udekoruj cukrem pudrem lub suszonymi owocami.","tip":"Ramę na cały stół wielkanocny daje [menu wielkanocne](/pl/blog/menu-wielkanocne), fokus tego przepisu zostaje jednak wyraźnie przy tym jednym mazurku."}]'::jsonb, 'Mazurek orzechowy, płaski i chrupiąco-orzechowy, świąteczny i do krojenia, Wielkanoc bez wysokiej babki z formy. Nazwa mazurek pochodzi od słowa Mazur, czyli dawnego określenia mieszkańca Mazowsza, mazurek był więc pierwotnie po prostu „ciastem mazowieckim”, tak jak taniec o tej samej nazwie jest tańcem mazowieckim. Najstarsze polskie słowniki nie łączyły go jeszcze ze świętami: u Lindego na początku XIX wieku mazurek to po prostu „placek z migdałów”. Jego korzenie sięgają orientalnej sztuki wyrobu słodyczy migdałowych, która dotarła do Polski przez kontakty handlowe z Imperium Osmańskim w XVII wieku i została dopracowana na dworach szlacheckich, podobne wypieki miały powstawać już wcześniej w kuchniach klasztornych. Na stałe z Wielkanocą połączyły go dopiero słowniki powojenne. Właśnie to pochodzenie tłumaczy charakterystyczną formę: cienki, chrupiący spód z bogatym wierzchem, a nie wysokie, wyrastające ciasto. To ani wysoka drożdżowa [babka](/pl/rezepte/babka), ani [sernik](/pl/rezepte/sernik), ani rolada [makowiec](/pl/rezepte/makowiec), ani korzenny [piernik](/pl/rezepte/piernik).

## Zakupy i gotowanie

Mąka, zimne masło, cukier i jajko budują spód, mieszanka orzechów i miód wierzch, oba te składniki znajdziesz często szczególnie świeże w [sklepie polskim](/pl/blog/sklep-polski-zakupy). Jeśli brakuje konkretnej odmiany orzechów, pomogą uczciwe [zamienniki składników](/pl/blog/zamienniki-skladnikow). Drożdże nie są tu potrzebne, kto szuka wyczucia ciasta drożdżowego, znajdzie je raczej w [technice makowca](/pl/blog/makowiec-technika). Wystarczy płaska blacha, forma jak do babki nie jest tu potrzebna.

Kruche ciasto trzeba wyrabiać krótko i na zimno, na ciepło robi się gumowate zamiast krótkiego i kruchego. Po cienkim rozwałkowaniu spód podpieka się wcześniej, a potem od razu na gorąco kładzie orzechy związane z masłem i miodem. Drugie pieczenie utwardza wierzch, nie paląc przy tym spodu, dlatego za pierwszym razem wystarczy lekkie złocenie. Zbyt gruba warstwa ciasta szybko przypomina spód ciasteczkowy bez charakteru mazurka, a zbyt mało wierzchu sprawia, że placek wygląda ubogo. Kroi się dopiero po całkowitym ostudzeniu, na gorąco wierzch łatwo pęka.

W Niemczech często piecze się w sobotę, a w niedzielę tylko układa na stole, co odciąża poranek wielkanocny. Dzieci mogą liczyć orzechy i układać romby, gorący piekarnik zostaje przy dorosłych. Jedna blacha wystarcza dla wielu gości, jakość liczy się tu bardziej niż trzy różne wypieki. Zakupy warto zrobić wcześnie w [sklepie polskim](/pl/blog/sklep-polski-zakupy), zanim półki z orzechami i miodem opustoszeją przed świętami.

## Przy stole

W romby lub prostokąty na półmisku, opcjonalnie z suszonymi owocami, przy stole wielkanocnym obok żurku i kolorowych jajek. Kto szuka wysokości i drożdży, znajdzie to w [babce](/pl/rezepte/babka), kto woli twaróg, w [serniku](/pl/rezepte/sernik), a kto chce spiralę makową, w [makowcu](/pl/rezepte/makowiec). Szczelnie zapakowany wierzch zostaje chrupiący przez kilka dni.

Zbyt gruby spód szybko przytłacza delikatny wierzch, a nałożenie go bez wcześniejszego podpieczenia spodu grozi rozmoknięciem całości. Łatwo pomylić go z wysoką [babką](/pl/rezepte/babka) lub [sernikiem](/pl/rezepte/sernik), choć to właśnie płaska forma jest jego znakiem rozpoznawczym. Krojenie na gorąco łamie wierzch zamiast dawać równe romby.

Wierzch kajmakowy zamiast orzechów to popularny zwyczaj domowy, który warto uczciwie zapowiedzieć w tytule, podobnie jak wersja tylko z orzechami włoskimi lub z suszonymi morelami. Pasującymi sąsiadami są [babka](/pl/rezepte/babka), [sernik](/pl/rezepte/sernik), [makowiec](/pl/rezepte/makowiec) i [piernik](/pl/rezepte/piernik). Do okazji pasuje [menu wielkanocne](/pl/blog/menu-wielkanocne), a zakupy ułatwią [sklep polski](/pl/blog/sklep-polski-zakupy) i [zamienniki składników](/pl/blog/zamienniki-skladnikow).', 'Mazurek przepis | Mazurek orzechowy wielkanocny | Alemniam', 'Mazurek orzechowy: kruche ciasto z orzechowym wierzchem. Dwujęzycznie, na Wielkanoc, jasno osobno od babki, sernika i makowca.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
